#!/usr/bin/env python3
from Crypto.Cipher import DES
import binascii
import itertools

# Constants
IV = b'13371337'
OFFSET = 9133337
WEAK_KEYS = [
    b'\x00\x00\x00\x00\x00\x00\x00\x00',
    b'\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF',
    b'\xE1\xE1\xE1\xE1\xF0\xF0\xF0\xF0',
    b'\x1F\x1F\x1F\x1F\x0E\x0E\x0E\x0E'
]

def pad_input(input_data):
    if len(input_data) % 8 != 0:
        return input_data + b'_' * (8 - len(input_data) % 8)
    return input_data

def des_encrypt(input_data, key):
    cipher = DES.new(key, DES.MODE_OFB, IV)
    return cipher.encrypt(pad_input(input_data))

def des_decrypt(input_data, key):
    cipher = DES.new(key, DES.MODE_OFB, IV)
    return cipher.decrypt(input_data)

def get_nibble_value(c):
    if '0' <= c <= '9':
        return int(c)
    return ord(c.lower()) - ord('a') + 10

def decode_custom(encoded_text):
    nibble_len = len(str(OFFSET)) + 1
    result = []

    i = 0
    while i < len(encoded_text):
        try:
            # Get two nibbles for one byte
            n1 = int(encoded_text[i:i+nibble_len]) - OFFSET
            n2 = int(encoded_text[i+nibble_len:i+2*nibble_len]) - OFFSET

            # Convert to hex chars
            if 0 <= n1 <= 9:
                n1 = str(n1)
            else:
                n1 = chr(ord('a') + (n1 - 10))

            if 0 <= n2 <= 9:
                n2 = str(n2)
            else:
                n2 = chr(ord('a') + (n2 - 10))

            result.append(n1 + n2)
            i += 2 * nibble_len
        except:
            break

    try:
        return binascii.unhexlify(''.join(result))
    except:
        return None

def test_key_pair(key1, key2):
    # Test with DES2Bytes.txt
    with open('DES2Bytes.txt', 'rb') as f:
        plaintext = f.read()

    # First encryption
    enc1 = des_encrypt(plaintext, key1)
    # Second encryption
    enc2 = des_encrypt(enc1, key2)

    # Read the encoded version
    with open('DES2Bytes.enc', 'r') as f:
        encoded = f.read().strip()

    # Decode and compare
    decoded = decode_custom(encoded)
    if decoded is None:
        return False

    return enc2 == decoded

def decrypt_flag(key1, key2):
    with open('FLAG.enc', 'r') as f:
        encoded = f.read().strip()

    # Decode the custom encoding
    decoded = decode_custom(encoded)
    if decoded is None:
        return None

    # Decrypt with key2 then key1
    dec2 = des_decrypt(decoded, key2)
    dec1 = des_decrypt(dec2, key1)

    return dec1

def main():
    print("Testing all weak key combinations...")
    # Test all combinations of weak keys
    for key1, key2 in itertools.product(WEAK_KEYS, WEAK_KEYS):
        print(f"Testing keys: {binascii.hexlify(key1).decode()} {binascii.hexlify(key2).decode()}")
        if test_key_pair(key1, key2):
            print(f"\nFound matching keys!")
            print(f"Key1: {binascii.hexlify(key1).decode()}")
            print(f"Key2: {binascii.hexlify(key2).decode()}")

            # Decrypt the flag
            flag = decrypt_flag(key1, key2)
            if flag:
                print("\nDecrypted flag:")
                try:
                    print(flag.decode('utf-8'))
                except:
                    print(flag)
            break

if __name__ == "__main__":
    main()

