from Crypto.Cipher import DES
import binascii

# Constants
IV = binascii.unhexlify('13371337')
OFFSET = 9133337
WEAK_KEYS = [
    '0000000000000000',
    'FFFFFFFFFFFFFFFF',
    'E1E1E1E1F0F0F0F0',
    '1F1F1F1F0E0E0E0E'
]

def decode_nibble(encoded_nibble):
    # Subtract offset from each encoded nibble
    try:
        return str(hex(int(encoded_nibble) - OFFSET)[2:])
    except:
        return '0'

def decode_custom(encoded_text):
    # Get the nibble length based on offset
    nibble_len = len(str(OFFSET)) + 1 if str(OFFSET)[0] == '9' else len(str(OFFSET))

    # Split text into nibbles and decode
    decoded = ''
    for i in range(0, len(encoded_text), nibble_len * 2):
        if i + nibble_len * 2 > len(encoded_text):
            break

        n1 = decode_nibble(encoded_text[i:i+nibble_len])
        n2 = decode_nibble(encoded_text[i+nibble_len:i+nibble_len*2])
        decoded += n1 + n2

    try:
        return binascii.unhexlify(decoded)
    except:
        return b''

def pad_input(input_data):
    if len(input_data) % 8 != 0:
        return input_data + b'_' * (8 - (len(input_data) % 8))
    return input_data

def decrypt_des_ofb(ciphertext, key1, key2):
    try:
        # First DES decryption
        cipher1 = DES.new(binascii.unhexlify(key1), DES.MODE_OFB, IV)
        intermediate = cipher1.decrypt(ciphertext)

        # Second DES decryption
        cipher2 = DES.new(binascii.unhexlify(key2), DES.MODE_OFB, IV)
        plaintext = cipher2.decrypt(intermediate)

        return plaintext
    except Exception as e:
        print(f"Error: {e}")
        return b''

def main():
    # Read the test files
    with open('DES2Bytes.txt', 'rb') as f:
        known_plaintext = f.read()
    with open('DES2Bytes.enc', 'r') as f:
        known_ciphertext = f.read()
    with open('FLAG.enc', 'r') as f:
        flag_ciphertext = f.read()

    # Decode the custom encoding
    decoded_known = decode_custom(known_ciphertext)
    decoded_flag = decode_custom(flag_ciphertext)

    if not decoded_known or not decoded_flag:
        print("Failed to decode ciphertexts")
        return

    # Try all weak key combinations
    print("Testing all weak key combinations...")
    for key1 in WEAK_KEYS:
        for key2 in WEAK_KEYS:
            print(f"\nTesting keys: {key1} {key2}")

            # Test with known plaintext first
            test_plaintext = decrypt_des_ofb(pad_input(decoded_known), key1, key2)
            if not test_plaintext:
                continue

            # Convert to string for comparison
            try:
                test_str = test_plaintext.decode('ascii', errors='ignore')
                if known_plaintext.decode('ascii', errors='ignore') in test_str:
                    print("Found matching keys!")
                    print(f"Key1: {key1}")
                    print(f"Key2: {key2}")

                    # Decrypt the flag
                    flag = decrypt_des_ofb(pad_input(decoded_flag), key1, key2)
                    if flag:
                        print("\nDecrypted Flag:")
                        print(flag.decode('ascii', errors='ignore'))
                    return
            except:
                continue

    print("No matching keys found")

if __name__ == '__main__':
    main()

